(139, 1, 'apdc5gjh3ndd82tgtambb7u40k', 'Sharing Session: Hasil Penelitian Dosen – Menguatkan Budaya Riset dan Hilirisasi Luaran Tridharma Perguruan Tinggi', 'Sharing Session: Hasil Penelitian Dosen merupakan kegiatan yang diselenggarakan oleh LPPM Universitas Bina Sarana Informatika Kampus Kota Tasikmalaya untuk memperkuat budaya riset dan diseminasi hasil penelitian dosen. Melalui sesi pemaparan dan diskusi interaktif, dosen peneliti berbagi pengalaman terkait penyusunan proposal, perolehan pendanaan, pelaksanaan penelitian, hingga luaran yang dihasilkan, seperti publikasi ilmiah, HKI, dan inovasi. Kegiatan ini memberikan wawasan mengenai pengelolaan riset, pelaporan penelitian, serta peluang pengembangan hasil penelitian, sekaligus mendorong kolaborasi dan peningkatan kualitas penelitian dosen secara berkelanjutan.\n\nEventHub code: EVT-945', 'J1-201', '2026-06-03 13:00:00', '2026-06-03 15:00:00', 0, 'https://www.google.com/calendar/event?eid=YXBkYzVnamgzbmRkODJ0Z3RhbWJiN3U0MGsgZXZlbnRtYXJrb21AYnNpLmFjLmlk&ctz=Asia/Jakarta', 'confirmed', '{\"kind\":\"calendar#event\",\"etag\":\"\\\"3563343006223534\\\"\",\"id\":\"apdc5gjh3ndd82tgtambb7u40k\",\"status\":\"confirmed\",\"htmlLink\":\"https://www.google.com/calendar/event?eid=YXBkYzVnamgzbmRkODJ0Z3RhbWJiN3U0MGsgZXZlbnRtYXJrb21AYnNpLmFjLmlk&ctz=Asia/Jakarta\",\"created\":\"2026-06-02T04:06:29.000Z\",\"updated\":\"2026-06-02T04:06:29.973Z\",\"summary\":\"Sharing Session: Hasil Penelitian Dosen \\u2013 Menguatkan Budaya Riset dan Hilirisasi Luaran Tridharma Perguruan Tinggi\",\"description\":\"Sharing Session: Hasil Penelitian Dosen merupakan kegiatan yang diselenggarakan oleh LPPM Universitas Bina Sarana Informatika Kampus Kota Tasikmalaya untuk memperkuat budaya riset dan diseminasi hasil penelitian dosen. Melalui sesi pemaparan dan diskusi interaktif, dosen peneliti berbagi pengalaman terkait penyusunan proposal, perolehan pendanaan, pelaksanaan penelitian, hingga luaran yang dihasilkan, seperti publikasi ilmiah, HKI, dan inovasi. Kegiatan ini memberikan wawasan mengenai pengelolaan riset, pelaporan penelitian, serta peluang pengembangan hasil penelitian, sekaligus mendorong kolaborasi dan peningkatan kualitas penelitian dosen secara berkelanjutan.\\n\\nEventHub code: EVT-945\",\"location\":\"J1-201\",\"creator\":{\"email\":\"eventmarkom@bsi.ac.id\",\"self\":true},\"organizer\":{\"email\":\"eventmarkom@bsi.ac.id\",\"self\":true},\"start\":{\"dateTime\":\"2026-06-03T13:00:00+07:00\",\"timeZone\":\"Asia/Jakarta\"},\"end\":{\"dateTime\":\"2026-06-03T15:00:00+07:00\",\"timeZone\":\"Asia/Jakarta\"},\"iCalUID\":\"apdc5gjh3ndd82tgtambb7u40k@google.com\",\"sequence\":0,\"reminders\":{\"useDefault\":false,\"overrides\":[{\"method\":\"popup\",\"minutes\":30},{\"method\":\"email\",\"minutes\":1440}]},\"eventType\":\"default\"}', '2026-06-08 17:34:06', '2026-07-13 06:53:07'),
